%[text] # Vehicle Speed Reference - Simulation Case
mdl = "VehSpdRef_TestModel";
load_system(mdl)
% No setup script is used with this harness model.
VehSpdRef_setRefsub_Simple %[output:0afbc053]
simOut = sim(mdl);
simData = extractTimetable(simOut.logsout);
VehSpdRef_ResultsPlot( SimData = simData ); %[output:159e74ac]
